import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2023Q4 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2023Q4 Ceph社区季度进展报告","date":"2023-12-01T00:00:00.000Z","updated":"2023-12-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/2023Q4_Ceph社区季度总结.md","filePath":"posts/2023/2023Q4_Ceph社区季度总结.md","lastUpdated":1780460162000}'),r={name:"posts/2023/2023Q4_Ceph社区季度总结.md"};function n(h,e,l,s,_,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ceph-社区-2023q4-季度进展报告" tabindex="-1">Ceph 社区 2023Q4 季度进展报告 <a class="header-anchor" href="#ceph-社区-2023q4-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2023Q4 季度进展报告&quot;">​</a></h1><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区的讨论高度集中在以下几个技术方向：</p><p><strong>RGW 通知系统重构</strong> SNS 主题权限管理、多站点通知复制、Bucket Notification V2 的设计与迁移路径贯穿整个季度，是讨论频次最高的议题。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-06.html">Ceph RGW Refactoring Meeting 2023-09-06</a>)、<a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-15.html">Ceph RGW Refactoring Meeting 2023-11-15</a>)、<a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-12-13.html">Ceph RGW Refactoring Meeting 2023-12-13</a>)。</p><p><strong>RGW IAM 与账户体系设计</strong> 账户所有权模型、配额管理、角色权限归属等 IAM 相关议题从 10 月持续讨论至 12 月，是本季度架构层面最重要的设计工作。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-25.html">Ceph RGW Refactoring Meeting 2023-10-25</a>)、<a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-12-13.html">Ceph RGW Refactoring Meeting 2023-12-13</a>)。</p><p><strong>多站点数据同步可靠性</strong> 数据日志竞态条件、生命周期与复制的交互问题、多站点测试稳定性，是本季度多站点方向的核心挑战。</p><p><strong>RADOS 层能力扩展</strong> 审计日志持久化、去重机制改进两个 RFE 在 CDM 会议中被提出，代表了 RADOS 层的新需求方向。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="rgw-通知系统" tabindex="-1">RGW 通知系统 <a class="header-anchor" href="#rgw-通知系统" aria-label="Permalink to &quot;RGW 通知系统&quot;">​</a></h3><ul><li><strong>SNS 主题权限收紧</strong>：明确将主题与创建者用户绑定，修复任意用户可管理他人主题的安全问题，并计划通过策略（Policy）机制管理跨用户访问。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-06.html">Ceph RGW Refactoring Meeting 2023-09-06</a>)。</li><li><strong>持久通知性能优化</strong>：评估了增加 Kafka 工作线程的方案，结论是瓶颈在写入队列侧而非消费侧，计划增加 Kafka 客户端统计指标以辅助诊断。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-20.html">Ceph RGW Refactoring Meeting 2023-09-20</a>)。</li><li><strong>Bucket Notification V2 功能标志</strong>：将功能标志从 &quot;notification syncing&quot; 重命名为 &quot;notification V2&quot;，确认为全局标志，并开始规划从旧数据模型的迁移路径。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-12-13.html">Ceph RGW Refactoring Meeting 2023-12-13</a>)。</li></ul><h3 id="多站点数据同步" tabindex="-1">多站点数据同步 <a class="header-anchor" href="#多站点数据同步" aria-label="Permalink to &quot;多站点数据同步&quot;">​</a></h3><ul><li><strong>数据日志替代方案</strong>：Adam 提出用 omap 跟踪未同步的桶分片，替代现有数据日志机制，以解决无限增长和竞态条件问题。方案引入时间戳优先级排序，支持目标区域优先处理旧变更。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-18.html">Ceph RGW Refactoring Meeting 2023-10-18</a>)。</li><li><strong>生命周期与多站点复制冲突</strong>：确认 UTC 午夜触发的生命周期处理会导致大量删除操作堆积在日志中，使多站点复制看似暂停。决策方向是不记录生命周期删除操作，依赖本地删除，并引入 Rados QoS 控制速率。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-11.html">Ceph RGW Refactoring Meeting 2023-10-11</a>)。</li><li><strong>多站点删除标记一致性</strong>：确认版本控制桶中生命周期过期操作在多站点间产生不一致删除标记版本 ID 的问题，并列入后续修复计划。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-12-13.html">Ceph RGW Refactoring Meeting 2023-12-13</a>)。</li></ul><h3 id="iam-与账户体系" tabindex="-1">IAM 与账户体系 <a class="header-anchor" href="#iam-与账户体系" aria-label="Permalink to &quot;IAM 与账户体系&quot;">​</a></h3><ul><li><strong>根账户所有权模型</strong>：确立根账户（root account）作为唯一具有所有权概念的主体，OIDC Provider、策略、配额均在账户级别管理，而非用户级别。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-25.html">Ceph RGW Refactoring Meeting 2023-10-25</a>)。</li><li><strong>角色归属账户</strong>：明确角色应由账户拥有而非单个用户，并重新审视 admin caps 在权限模型中的使用方式。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-12-13.html">Ceph RGW Refactoring Meeting 2023-12-13</a>)。</li><li><strong>动态重分片改进</strong>：提出在重分片队列中添加时间戳以支持延迟执行，并考虑在桶创建 API 中暴露分片计数字段。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-15.html">Ceph RGW Refactoring Meeting 2023-11-15</a>)。</li></ul><h3 id="依赖库与基础设施" tabindex="-1">依赖库与基础设施 <a class="header-anchor" href="#依赖库与基础设施" aria-label="Permalink to &quot;依赖库与基础设施&quot;">​</a></h3><ul><li><strong>librdkafka 版本问题</strong>：当前发行版中的 librdkafka 版本过旧，存在崩溃和 TLS 证书功能缺失问题。决定以子模块方式引入新版本并静态链接作为临时方案，同时向 CentOS 和 Ubuntu 提交 bug 报告请求更新。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-08.html">Ceph RGW Refactoring Meeting 2023-11-08</a>)。</li><li><strong>Coverity 静态分析</strong>：系统性使用 Coverity 扫描 RGW 代码，识别出空引用、内存泄漏、未初始化变量等问题，约 40% 为误报，讨论将其纳入 CI 流程。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-27.html">Ceph RGW Refactoring Meeting 2023-09-27</a>)。</li></ul><h3 id="rados-层" tabindex="-1">RADOS 层 <a class="header-anchor" href="#rados-层" aria-label="Permalink to &quot;RADOS 层&quot;">​</a></h3><ul><li><strong>审计日志持久化 RFE</strong>：CephFS 团队提出在 RADOS 中持久化存储审计日志的需求，计划开发新的 Manager 模块，支持用户选择性保存、权限控制和保留策略配置。</li><li><strong>去重机制改进</strong>：现有去重实现对小数据块效率低下，提出将小块打包到大对象中的新机制，需进一步性能测试。详见 <a href="/VideoSummary/posts/2023/Ceph_Developer_Monthly_2023-10-04.html">Ceph Developer Monthly 2023-10-04</a>)。</li></ul><h3 id="lua-集成与认证" tabindex="-1">Lua 集成与认证 <a class="header-anchor" href="#lua-集成与认证" aria-label="Permalink to &quot;Lua 集成与认证&quot;">​</a></h3><ul><li><strong>Lua API 重组</strong>：讨论了 Lua 脚本与 HTTP 头信息暴露的问题，提出重新组织 Lua API 以提供更清晰、安全的访问方式。</li><li><strong>LDAP 弃用计划</strong>：提出在下一个主要版本中弃用 LDAP 独立认证机制，建议迁移至 STS（Security Token Service）。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-29.html">Ceph RGW Refactoring Meeting 2023-11-29</a>)。</li></ul><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><p>| 决策 | 内容 | 来源 | |------|------| | SNS 主题与用户绑定 | 主题归属创建者，修复权限漏洞 | <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-06.html">2023-09-06</a>) | | 数据日志替代方案方向 | 倾向 omap 方案，避免日志无限增长 | <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-18.html">2023-10-18</a>) | | 账户所有权模型确立 | 根账户持有所有权，配额在账户级管理 | <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-25.html">2023-10-25</a>) | | Notification V2 功能标志命名 | 重命名为 &quot;notification V2&quot;，确认全局标志 | <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-12-13.html">2023-12-13</a>) | | librdkafka 子模块引入 | 静态链接新版本作为临时方案 | <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-08.html">2023-11-08</a>) | | LDAP 弃用计划启动 | 下一主要版本宣布弃用，迁移至 STS | <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-29.html">2023-11-29</a>) | | Manager 模块加载修复方向 | 异步加载 Python 模块，延迟设置可用性标志 | <a href="/VideoSummary/posts/2023/Ceph_Developer_Monthly_2023-12-06.html">2023-12-06</a>) |</p><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><p><strong>定期会议</strong> 本季度 RGW Refactoring Meeting 保持每周一次的节奏，共记录 9 次会议（9 月至 12 月），覆盖通知、多站点、IAM、数据日志等多个子方向，参与者包括 Adam、Casey、Matt、Jane、Eric、Ali 等核心贡献者。</p><p><strong>Ceph Developer Monthly</strong></p><ul><li>10 月 CDM 聚焦 RADOS 层新需求（审计日志、去重），体现了上层应用对存储层能力的新诉求。</li><li>12 月 CDM 讨论了 Manager 模块加载的竞态问题，涉及 Python 模块异步加载机制的改进。详见 <a href="/VideoSummary/posts/2023/Ceph_Developer_Monthly_2023-12-06.html">Ceph Developer Monthly 2023-12-06</a>)。</li></ul><p><strong>Ceph User + Dev Monthly</strong> 11 月的用户开发联合会议由 Zach Dober 主持，重点推进《Ceph 入门指南》文档工作，收集社区对文档内容的反馈，计划增加高层次架构图和&quot;试驾文档&quot;。这反映了社区对降低新用户门槛的持续投入。详见 <a href="/VideoSummary/posts/2023/Ceph_User_+_Dev_Monthly_2023-11-16.html">Ceph User + Dev Monthly 2023-11-16</a>)。</p><p><strong>感恩节影响</strong> 11 月 22 日会议因感恩节假期部分成员缺席，Jane 的多站点重试 PR 讨论顺延至下周，体现了北美社区的节假日节奏。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-22.html">Ceph RGW Refactoring Meeting 2023-11-22</a>)。</p><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度讨论内容，预计 2024Q1 将重点推进以下方向：</p><ol><li><p><strong>Bucket Notification V2 迁移路径落地</strong>：功能标志已确认，迁移代码路径的实现和测试将是近期重点，需处理旧数据模型的兼容升级。</p></li><li><p><strong>RGW 账户体系 PR 推进</strong>：用户账户 PR 已有详细待办列表，角色归属账户的权限模型已明确，预计进入实质性代码审查和测试阶段。</p></li><li><p><strong>数据日志替代方案实现</strong>：omap 方案的 CLS 条目修改和 REST 接口完善已列入计划，需同步考虑向后兼容性。</p></li><li><p><strong>多站点测试稳定性改善</strong>：本季度多次提及多站点测试不稳定，预计会有专项改进投入，包括测试基础设施优化。</p></li><li><p><strong>librdkafka 上游推进</strong>：子模块方案为临时方案，需持续跟进 CentOS/Ubuntu 的版本更新，并评估是否长期保留子模块。</p></li><li><p><strong>LDAP 弃用文档与迁移指南</strong>：弃用计划已启动，需在正式发版前完成迁移文档和 Tracker 跟踪。</p></li><li><p><strong>RADOS 审计模块原型</strong>：审计日志 RFE 已获社区认可，预计进入 API 设计和原型开发阶段。</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2023/Ceph_Developer_Monthly_2023-10-04.html">CephDeveloperMonthly2023-10-04</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_Developer_Monthly_2023-12-06.html">Ceph Developer Monthly 2023-12-06</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-06.html">Ceph RGW Refactoring Meeting 2023-09-06</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-20.html">Ceph RGW Refactoring Meeting 2023-09-20</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-27.html">Ceph RGW Refactoring Meeting 2023-09-27</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-11.html">Ceph RGW Refactoring Meeting 2023-10-11</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-18.html">Ceph RGW Refactoring Meeting 2023-10-18</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-25.html">Ceph RGW Refactoring Meeting 2023-10-25</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-08.html">Ceph RGW Refactoring Meeting 2023-11-08</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-15.html">Ceph RGW Refactoring Meeting 2023-11-15</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-22.html">Ceph RGW Refactoring Meeting 2023-11-22</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-29.html">Ceph RGW Refactoring Meeting 2023-11-29</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-12-13.html">Ceph RGW Refactoring Meeting 2023-12-13</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_User_+_Dev_Monthly_2023-11-16.html">Ceph User + Dev Monthly 2023-11-16</a>)</li></ul>',38)])])}const R=t(r,[["render",n]]);export{m as __pageData,R as default};
